from __future__ import annotations

from fractions import Fraction
from typing import Mapping

_ORDER = 4
_TURN = ((Fraction(0), Fraction(-1)), (Fraction(1), Fraction(0)))
_IDENTITY = ((Fraction(1), Fraction(0)), (Fraction(0), Fraction(1)))


class RotationError(Exception):
    """One violated rotation invariant, with the measured parameters."""

    def __init__(self, invariant: str, parameters: Mapping[str, object] | None = None) -> None:
        self.invariant = invariant
        self.parameters = {} if parameters is None else dict(parameters)
        rendered = ", ".join(f"{key}={value}" for key, value in self.parameters.items())
        message = invariant if rendered == "" else f"{invariant} ({rendered})"
        super().__init__(message)


def _fail(invariant: str, **parameters: object) -> RotationError:
    return RotationError(invariant, parameters)


def _require_fraction(value: object, role: str) -> Fraction:
    if isinstance(value, float):
        raise _fail("float refused at the public boundary", role=role, received="float")
    if type(value) is bool:
        raise _fail("boolean refused where a rational was required", role=role)
    if isinstance(value, Fraction):
        return value
    if type(value) is int:
        return Fraction(value)
    raise _fail("value is not an exact rational", role=role, received=type(value).__name__)


def _entry(left: tuple[tuple[Fraction, Fraction], tuple[Fraction, Fraction]], right: tuple[tuple[Fraction, Fraction], tuple[Fraction, Fraction]], row: int, column: int) -> Fraction:
    return left[row][0] * right[0][column] + left[row][1] * right[1][column]


def _mul(left: tuple[tuple[Fraction, Fraction], tuple[Fraction, Fraction]], right: tuple[tuple[Fraction, Fraction], tuple[Fraction, Fraction]]) -> tuple[tuple[Fraction, Fraction], tuple[Fraction, Fraction]]:
    return ((_entry(left, right, 0, 0), _entry(left, right, 0, 1)), (_entry(left, right, 1, 0), _entry(left, right, 1, 1)))


def quarter_turn_order() -> int:
    """Smallest positive exponent with R^n = I. It is 4."""
    current = _IDENTITY
    exponent = 1
    while exponent <= 8:
        current = _mul(current, _TURN)
        if current == _IDENTITY:
            if exponent != _ORDER:
                raise _fail("quarter turn order drifted", order=exponent)
            return exponent
        exponent += 1
    raise _fail("quarter turn did not return to the identity", bound=8)


def _locked(value: Fraction, expected: Fraction, invariant: str) -> Fraction:
    if value != expected:
        raise _fail(invariant, value=str(value), expected=str(expected))
    return value


_MARK = 7


def _mark() -> int:
    return _MARK


def certify(probe: object | None = None) -> Fraction:
    """Refuse a non-rational probe, then return the quarter-turn order 4."""
    if probe is not None:
        _require_fraction(probe, "probe")
    if _mark() != 7:
        raise _fail("certificate mark drifted", mark=_mark())
    return _locked(Fraction(quarter_turn_order()), Fraction(_ORDER), "quarter turn order drifted")


def main() -> int:
    value = quarter_turn_order()
    print(value)
    if value == _ORDER:
        return 0
    return 1


if __name__ == "__main__":
    raise SystemExit(main())
